      const wrapper = mount(BTable, {
        props: {
          'selectMode': 'multi' as const,
          'selectable': true,
          items,
          'selectedItems': [],
          'onUpdate:selectedItems': (value) => wrapper.setProps({selectedItems: value}),
        },
      })
      const $trs = wrapper.findAll('tr')
